export const DATA_99: ReadingTest[] = [
  { id: "rd-186", num: 186, title: "Đề 186", timeMin: 60, parts: [
    { title: "Food Trends: Why What We Eat Keeps Changing", paragraphs: ["Walk into almost any supermarket today and you will notice foods that barely existed on the shelves ten years ago — plant-based burgers, oat milk, and brightly colored energy drinks. Food trends, the popular tastes and habits that spread quickly among large groups of people, change faster now than they once did. Three forces mainly drive this constant change: growing health awareness, greater convenience, and the powerful reach of social media, where a single video can turn an unfamiliar dish into a nationwide craving within weeks. Understanding why these trends appear, and why they fade, says as much about modern life as it does about food itself.", "Health awareness is probably the clearest driver. As more people learn about the links between diet and long-term illness, many shoppers now read nutrition labels carefully before buying anything. This shift explains why plant-based meat substitutes, once found only in specialty stores, now sit beside traditional meat in most supermarkets. Sales of these products have grown quickly in the past five years, even though many consumers admit the taste still does not fully match real meat. For them , the potential health benefit is worth the trade-off in flavor.", "Convenience plays an equally important role, especially among people with busy work schedules. Meal-kit services, which deliver pre-measured ingredients and simple recipes to a customer's door, grew rapidly during the past decade because they promise a home-cooked meal without the usual planning or grocery shopping. Frozen and ready-to-eat meals have also improved in quality, no longer carrying the poor reputation they once had. Many young professionals now choose these options several times a week, saving time on both shopping and cooking without giving up the feeling of a proper dinner.", "Social media, however, may now be the single fastest way a food trend spreads. A short video showing an unusual snack or a colorful drink can reach millions of viewers within days, and restaurants sometimes see long lines form outside their doors the very next morning. Some food trends started this way disappear almost as quickly as they arrived, once viewers move on to the next viral clip. Restaurant owners increasingly say they must watch social media closely, not just to follow trends but to react to them within days, since waiting even a single week can mean missing a trend entirely.", "Taken together, these three forces suggest that food trends are unlikely to slow down anytime soon. Whether a new trend reflects a genuine shift in how people think about health, a simple demand for convenience, or nothing more than a passing moment of online attention, it now spreads faster and disappears faster than trends of previous decades. For food companies, this means constantly watching what people are eating and talking about, ready to adjust their products at a pace that would have seemed unusual only twenty years ago."], questions: [{ q: "According to the passage, what are the three main forces driving changes in food trends?", options: ["Health awareness, convenience, and traditional advertising", "Convenience, social media, and restaurant advertising", "Health awareness, convenience, and social media", "Health awareness, government policy, and price"], answer: 2 }, { q: "What is the main idea of the passage?", options: ["Health, convenience, and social media together speed up food trends", "Plant-based meat substitutes have completely replaced real meat sales", "Social media matters far more than health or convenience combined", "Food trends have remained mostly unchanged over the past decade"], answer: 0 }, { q: "The word \"craving\" in paragraph 1 is closest in meaning to _______.", options: ["health benefit", "crafting", "strong desire", "mild interest"], answer: 2 }, { q: "According to the passage, why did meal-kit services grow rapidly?", options: ["They deliver pre-measured ingredients and recipes without usual planning", "They replaced the need for any home cooking entirely", "They were mainly promoted through television advertising campaigns", "They cost significantly less than any other grocery option"], answer: 0 }, { q: "According to the passage, which of the following is NOT mentioned as a reason food trends spread quickly?", options: ["Government subsidies lowering the price of certain foods", "Busy work schedules increasing demand for convenience", "Growing awareness of links between diet and illness", "Short videos reaching millions of viewers quickly"], answer: 0 }, { q: "The word \"them\" (in \"For them, the potential health benefit,\" paragraph 2) refers to _______.", options: ["specialty stores", "plant-based substitutes", "many consumers", "nutrition labels"], answer: 2 }, { q: "What does the passage say can happen after a food video becomes popular online?", options: ["Restaurants usually close down within the same week", "Prices for the featured food always double overnight", "Governments often step in to regulate the trend", "Long lines can form outside restaurants the next morning"], answer: 3 }, { q: "The word \"trade-off\" in paragraph 2 is closest in meaning to _______.", options: ["discount", "tradition", "compromise", "delay"], answer: 2 }, { q: "What can be inferred from the passage about restaurant owners' attitude toward social media?", options: ["They increasingly feel pressure to respond to trends within days", "They think waiting several weeks to respond causes no real harm", "They believe social media trends have no effect on their sales", "They report that only television advertising still matters for business"], answer: 0 }, { q: "What is the author's overall attitude toward the pace of change in food trends?", options: ["Dismissive, suggesting food trends are unimportant and rarely noticed", "Enthusiastic, urging readers to try every new food trend immediately", "Observational, describing forces behind trends without strong judgment", "Alarmed, warning readers about serious dangers of new food products"], answer: 2 }] },
    { title: "Rethinking What It Means to Grow Older", paragraphs: ["For much of the twentieth century, popular culture treated aging almost exclusively as a story of decline — a period defined by loss rather than gain. In recent years, however, a small but growing body of psychological research has begun to challenge that narrative directly, suggesting that many aspects of well-being do not simply decrease with age but, for a significant number of people, actually improve well into later life.", "Emotional regulation, several long-term studies now indicate, tends to improve steadily from early adulthood into a person's seventies, even as memory and processing speed decline over the same period. Older adults, according to this research, generally report fewer negative emotions and recover from stressful events more quickly than younger adults tested under comparable conditions. Researchers describe this pattern as counterintuitive precisely because it runs against the assumption that overall psychological functioning simply worsens with age; instead, different capacities appear to follow entirely different trajectories, some declining while others continue to strengthen.", "One explanation, proposed by psychologist Laura Carstensen and now widely cited, holds that as people become more aware of limited remaining time, they tend to prioritize emotionally meaningful relationships and experiences over the pursuit of new information or social expansion. This shift, sometimes called socioemotional selectivity, may account for why older adults often report smaller but more satisfying social circles than they had in their twenties, even though the underlying mechanism remains debated among researchers who study motivation more broadly.", "None of this is meant to suggest that aging carries no real physical or cognitive costs. Rates of certain chronic illnesses do rise substantially with age, and some cognitive functions, particularly the speed of processing new information, decline measurably over time. What the newer research challenges is not the existence of these costs but the assumption that they define the overall experience of growing older, rather than existing alongside genuine psychological gains that popular narratives have historically overlooked.", "This shift in scientific understanding has coincided with, though not necessarily caused, a broader cultural movement toward what some writers now call age-positive marketing and media — advertising campaigns featuring older models, television shows centered on characters in their sixties and seventies, and public celebrations of milestone birthdays that once might have been treated as occasions for quiet reflection rather than celebration. Critics argue that some of this messaging remains superficial , celebrating age mainly through the appearance of vitality rather than engaging with its genuine complexity.", "This cultural shift, whether it reflects or merely coincides with the psychological findings described earlier, remains an open question that current research cannot fully settle, particularly since most studies on emotional well-being in later life have drawn heavily on relatively affluent, healthy populations rather than the full range of people who experience aging under more difficult economic or health circumstances.", "Taken together, these findings suggest that growing older is neither the uniform decline nor the uniformly celebrated experience that competing popular narratives often present. Rather, aging appears to involve real losses in some domains occurring alongside genuine gains in others, a more complicated picture than either the old story of decline or the newer, more celebratory one fully captures. Recognizing this complexity, several researchers argue, may matter more for public policy and personal expectations than settling on either narrative as complete."], questions: [{ q: "According to the passage, what does the passage say about chronic illness rates and aging?", options: ["They rise substantially with age, alongside genuine psychological gains", "They rise only among people who reject age-positive cultural messaging", "They remain identical across all age groups studied", "They decrease significantly once emotional regulation improves with age"], answer: 0 }, { q: "The word \"counterintuitive\" in paragraph 2 is closest in meaning to _______.", options: ["predictable", "emotional", "surprising", "controversial"], answer: 2 }, { q: "What is the main idea of the passage?", options: ["Cultural celebrations of aging have fully replaced negative stereotypes about age", "Scientific research proves that aging is now a purely positive experience", "Emotional regulation is the only ability that changes as people age", "Aging involves real losses alongside genuine, often overlooked psychological gains"], answer: 3 }, { q: "According to the passage, what pattern do long-term studies report about emotional regulation and age?", options: ["It declines at exactly the same rate as memory and processing speed", "It tends to improve steadily even as memory and processing speed decline", "It remains completely unchanged throughout adulthood regardless of age", "It improves only among adults who have professional psychological training"], answer: 1 }, { q: "According to the passage, which of the following is NOT mentioned as part of the age-positive cultural movement?", options: ["Government funding directed at elder-care research", "Public celebrations of milestone birthdays", "Television shows centered on older characters", "Advertising campaigns featuring older models"], answer: 0 }, { q: "The word \"This\" (in \"This cultural shift,\" paragraph 6) refers to _______.", options: ["the chronic-illness increase", "the processing-speed decline", "the age-positive marketing movement", "the motivation researchers' debate"], answer: 2 }, { q: "According to the passage, what does socioemotional selectivity theory suggest about older adults?", options: ["They tend to prioritize meaningful relationships over expanding their social circle", "They generally lose interest in emotionally meaningful relationships altogether", "They actively seek out unfamiliar information rather than close relationships", "They tend to avoid close relationships in favor of new social contacts"], answer: 0 }, { q: "The word \"superficial\" in paragraph 5 is closest in meaning to _______.", options: ["artificial", "shallow", "supportive", "temporary"], answer: 1 }, { q: "What can be inferred from the passage about the populations most studied in emotional well-being research on aging?", options: ["They have included equal numbers of people across all income levels", "They have mainly been relatively affluent and healthy, limiting how broadly findings apply", "They have been studied mainly in countries without any healthcare systems", "They have focused exclusively on people experiencing serious chronic illness"], answer: 1 }, { q: "What is the author's overall purpose in this passage?", options: ["To criticize researchers for ignoring the physical costs of aging", "To present a more complex picture of aging than either narrative alone", "To argue that aging should always be celebrated without qualification", "To prove that cultural marketing has caused psychological changes in aging"], answer: 1 }] },
    { title: "The Quiet Exodus: Why Young People Leave Their Hometowns", paragraphs: ["Across much of the world, small towns and rural regions share a demographic pattern that has become increasingly difficult to reverse: a steady, cumulative departure of young adults toward larger cities, leaving behind populations that skew progressively older with each passing decade. The conventional explanation, that young people simply follow better-paying jobs, captures part of the story but obscures a more complicated set of motivations that recent sociological research has begun to untangle, motivations that persist even in regions where local wages have kept pace with those in nearby cities.", "Economic opportunity alone, it turns out, predicts emigration far less reliably than researchers once assumed. Towns offering comparable wages to those in nearby metropolitan areas often still lose a disproportionate share of their young residents, while some lower-wage towns retain them at surprisingly high rates. What appears to matter more, several longitudinal studies now suggest, is not the absolute wage a young person could earn locally, but the perceived range of life paths available to them — whether staying open a plausible route toward the kind of adulthood they envision, or whether it appears to foreclose it.", "This perception, researchers argue, is shaped less by economic statistics than by a young person's exposure to visible models of adult life within their own community. In towns where most successful adults left and returned only occasionally, or where the most visible career paths are concentrated in a narrow set of industries, adolescents may come to associate staying with limited horizons long before they enter the labor market themselves. Whether this effect is strongest during adolescence or persists into early adulthood remains disputed, though several studies point to the years immediately preceding a person's first major career decision as particularly influential.", "None of this suggests that wages are irrelevant. Where local employment genuinely disappears — following a factory closure, for instance, or the decline of an agricultural sector — outmigration accelerates sharply regardless of how residents perceive their prospects, and no amount of community narrative appears able to offset the absence of viable work entirely. The perception-based account, in other words, seems to operate most powerfully in the broad middle range of local economies: those neither collapsing outright nor obviously thriving, where the decision to stay or leave is genuinely open to interpretation.", "Some regional governments have responded by investing not in wage subsidies but in what researchers term 'visibility interventions' — mentorship programs, local business showcases, and return-migrant networks designed to make a wider range of adult life paths locally visible to adolescents well before they leave for higher education. Early evaluations of these programs report modestly higher return rates among young adults who leave temporarily for study, though the studies acknowledge that isolating the intervention's effect from other regional changes occurring simultaneously remains methodologically difficult.", "Critics of the visibility-intervention approach note that such programs cannot, on their own, replace employment in regions where the underlying economic base has genuinely deteriorated , of the kind described earlier; a mentorship program offers little practical value to a young adult in a town with no available jobs regardless of local career narratives. Whether visibility interventions meaningfully complement, rather than merely supplement, more traditional economic development efforts remains an open empirical question that current program evaluations have not yet resolved.", "Taken together, these findings suggest that reversing youth outmigration requires more than matching urban wages, though wages remain a necessary floor beneath any other intervention. Communities hoping to retain young residents may need to address not only what work is locally available but also what that work appears to represent about the range of futures still open to someone who chooses to stay — a more difficult, and more gradual, undertaking than any single wage incentive can accomplish on its own."], questions: [{ q: "According to the passage, what have longitudinal studies found about towns offering wages comparable to nearby cities?", options: ["They consistently retain more young residents than lower-wage towns do", "They retain young residents whenever visibility programs are introduced", "They often still lose many young residents", "They lose residents only when local factories or farms close down"], answer: 2 }, { q: "The word \"foreclose\" in paragraph 2 is closest in meaning to _______.", options: ["rule out", "delay", "announce", "finance"], answer: 0 }, { q: "What is the main idea of the passage?", options: ["Perceived life paths, not wages alone, largely explain youth outmigration", "Wage subsidies are the only effective solution to rural outmigration", "Young people leave hometowns solely because of factory closures", "Visibility interventions have fully solved youth outmigration in most regions"], answer: 0 }, { q: "According to the passage, what may shape a young person's perception of local opportunity before they even enter the labor market?", options: ["Their exposure to visible models of adult life within the community", "The number of universities located within the immediate region", "The specific wage levels published in regional government reports", "Formal career counseling sessions provided during adolescence"], answer: 0 }, { q: "According to the passage, which of the following is NOT mentioned as a factor influencing youth outmigration?", options: ["Genuine local job loss following a factory or agricultural decline", "Visible models of adult life within the community", "The average commuting distance to the nearest large city", "Participation in mentorship or return-migrant network programs"], answer: 2 }, { q: "The word \"this\" (in \"None of this suggests,\" paragraph 4) refers to _______.", options: ["the wage subsidy programs mentioned in paragraph 5", "the perception-based explanation described in paragraphs 2 and 3", "the factory closures described in paragraph 4 itself", "the visibility-intervention programs described in paragraph 5"], answer: 1 }, { q: "According to the passage, what do early evaluations of visibility interventions report?", options: ["Slightly higher return rates for student movers", "A complete reversal of outmigration trends within two years", "No measurable effect on return rates among young adults", "Higher return rates only among adults who never left at all"], answer: 0 }, { q: "The word \"deteriorated\" in paragraph 6 is closest in meaning to _______.", options: ["regulated", "relocated", "diversified", "worsened"], answer: 3 }, { q: "What can be inferred from the passage about the effectiveness of visibility interventions in regions with no available jobs?", options: ["They have been shown to eliminate youth outmigration entirely", "They are proven to fully replace the need for local employment", "They likely offer little practical value", "They mainly benefit towns that have already lost their agricultural sector"], answer: 2 }, { q: "What is the author's overall purpose in the passage?", options: ["To prove that visibility interventions are more effective than any wage-based policy", "To offer a nuanced, perception-based view of youth outmigration", "To criticize regional governments for failing to fund mentorship programs", "To argue that wage increases are irrelevant to solving youth outmigration"], answer: 1 }] },
    { title: "Complementary Medicine and the Limits of the Evidence Hierarchy", paragraphs: ["Complementary and alternative medicine — a broad category encompassing practices ranging from acupuncture and herbal remedies to meditation-based stress reduction — occupies an increasingly uneasy position within contemporary healthcare systems. Not only have surveys consistently found that a substantial minority of patients in wealthy countries use some form of complementary treatment alongside conventional care, but many report doing so without informing their physicians, a pattern that complicates any straightforward assessment of how widely, and how safely, these practices are actually integrated into routine medical decision-making.", "Whether this integration should be encouraged, tolerated, or actively discouraged remains a matter of considerable disagreement among clinicians and researchers, and the disagreement, on close examination, turns out to hinge less on whether any given complementary practice works than on how rigorously 'working' must be demonstrated before a treatment earns a place in mainstream care. Randomized controlled trials, long treated as the evidentiary gold standard in conventional medicine, have produced genuinely mixed results when applied to complementary practices — strongly positive for some interventions, such as certain uses of acupuncture for chronic pain, and essentially null for others.", "Proponents of a more permissive evidentiary standard argue that the randomized controlled trial, however well suited to evaluating a single pharmaceutical compound, may systematically undervalue interventions whose effects depend heavily on context — the relationship between practitioner and patient, ritual and expectation, or a treatment's fit within a patient's broader belief system — variables that trials are typically designed to control away rather than measure. This argument does not claim that such context effects make a treatment equally effective for every condition, only that conventional trial design may be poorly suited to detecting benefits that arise primarily through mechanisms trials were never built to capture in the first place.", "Critics of this position counter that context effects, whatever their genuine influence on a patient's subjective experience, rarely translate into measurable improvement in objective clinical outcomes — tumor size, blood markers, mortality — and that treatments justified primarily by reference to context risk becoming, in practice, unfalsifiable : any failure to demonstrate benefit can always be attributed to insufficiently attentive delivery rather than to the treatment's actual inefficacy. Whether this concern applies equally to all complementary practices, or mainly to those making the strongest causal claims about physiological mechanisms, remains a point on which even skeptical researchers do not fully agree.", "Acupuncture, again, illustrates the resulting uncertainty particularly well. Meta-analyses examining acupuncture for chronic pain report a small but statistically significant benefit over no treatment, yet the same analyses frequently find little difference between genuine acupuncture and sham acupuncture, in which needles are inserted at non-therapeutic points or fail to penetrate the skin at all. Some researchers interpret this pattern as evidence that acupuncture's benefit is substantially, though perhaps not entirely, attributable to placebo-adjacent mechanisms rather than the specific anatomical points targeted by traditional theory, a conclusion that practitioners of acupuncture frequently dispute on methodological grounds.", "Whether a treatment that outperforms no intervention, but not sham intervention, deserves a place in mainstream care depends heavily on how one resolves the evidentiary disagreement described earlier: a strict outcomes-only standard would tend to deprioritize such treatments, while a standard more sympathetic to context effects might still endorse them, provided the treatment carries minimal risk and its use does not displace more effective conventional care for serious conditions requiring it.", "None of this resolves the underlying disagreement about how complementary medicine should be evaluated, nor does it settle whether patients who use these treatments alongside conventional care are, on balance, well served by doing so. What the accumulated evidence does suggest, cautiously, is that blanket judgments — dismissing complementary medicine wholesale as pure placebo, or embracing it wholesale as equivalent to conventional treatment — both overstate the certainty that current research can actually support, regardless of which direction that overstatement happens to run."], questions: [{ q: "What is the main idea of the passage?", options: ["Blanket judgments about complementary medicine likely overstate what current evidence can support", "Randomized controlled trials are the only valid way to evaluate any medical treatment", "Acupuncture has been proven to work through purely psychological mechanisms", "Complementary medicine should never be integrated into mainstream healthcare systems"], answer: 0 }, { q: "According to the passage, what has been the general pattern in randomized controlled trial results for complementary practices?", options: ["Genuinely mixed across different interventions", "Uniformly negative, showing no benefit for any practice studied", "Too limited in number to draw any conclusions at all", "Uniformly positive across nearly every complementary practice tested"], answer: 0 }, { q: "The word \"unfalsifiable\" in paragraph 4 is closest in meaning to _______.", options: ["difficult to standardize", "impossible to disprove", "difficult to translate", "impossible to afford"], answer: 1 }, { q: "According to the passage, what do proponents of a more permissive evidentiary standard argue trials may fail to detect?", options: ["Benefits that depend entirely on a patient's genetic profile", "Benefits that occur only when a treatment is combined with medication", "Benefits that are visible exclusively in long-term mortality data", "Benefits from context-dependent mechanisms"], answer: 3 }, { q: "According to the passage, which of the following is NOT mentioned as a factor in the disagreement over evaluating complementary medicine?", options: ["Whether a treatment's use displaces more effective conventional care", "The total cost of complementary treatments compared to conventional care", "Whether context effects translate into measurable objective clinical outcomes", "How rigorously 'working' must be demonstrated before a treatment is accepted"], answer: 1 }, { q: "The phrase \"this concern\" (paragraph 4) refers to _______.", options: ["the risk that complementary treatments become impossible to disprove", "the risk that acupuncture harms patients physically", "the risk that randomized trials are too expensive to conduct", "the risk that patients hide treatment use from physicians"], answer: 0 }, { q: "What can be inferred from the passage about a treatment that outperforms no intervention but not sham intervention?", options: ["Its inclusion depends on the chosen evidentiary standard", "It is guaranteed to be included in mainstream care regardless of risk", "It has already been proven equivalent to conventional treatment for serious illness", "It is guaranteed to be excluded from mainstream care under any evidentiary standard"], answer: 0 }, { q: "The word \"attributable\" in paragraph 5 is closest in meaning to _______.", options: ["avoidable", "comparable", "traceable", "curable"], answer: 2 }, { q: "What is the author's overall attitude toward the debate over complementary medicine's evidentiary standards?", options: ["Balanced and cautious, presenting both sides without endorsing either fully", "Dismissive, treating complementary medicine as entirely without merit", "Strongly supportive of abandoning randomized controlled trials entirely", "Uncritically accepting, treating all complementary claims as already proven"], answer: 0 }, { q: "What do meta-analyses on acupuncture for chronic pain generally find?", options: ["A large benefit over no treatment and an equally large difference from sham acupuncture", "Consistent results only when the patient is unaware of receiving acupuncture", "No benefit over no treatment but a strong difference from sham acupuncture", "A small benefit over no treatment but little difference from sham acupuncture"], answer: 3 }] },
  ] },
  { id: "rd-188", num: 188, title: "Đề 188", timeMin: 60, parts: [
    { title: "Reconnecting with Old Friends", paragraphs: ["Most people can think of at least one old friend they have lost touch with over the years — someone from school, a former neighbor, or a colleague from an early job. Life gets busy, people move to new cities, and small gaps between messages slowly turn into years of silence. Yet many people who finally reach out to an old friend after a long break say the reunion feels surprisingly easy, almost as if no time had passed at all. Psychologists who study friendship have started paying closer attention to why reconnecting with someone from the past can feel so rewarding .", "One reason seems to be shared history. Old friends often remember details about your younger self that newer friends simply never had the chance to witness, such as an embarrassing haircut, a childhood nickname, or a difficult period you went through together. Talking with someone who remembers these details can create a sense of being fully known, since the friend understands not just who you are now but also how you became that person. This kind of understanding usually takes years to build with a brand-new friend.", "Reconnecting can also bring real benefits for mental health. Several studies have found that people with a wider circle of long-term social connections tend to report lower levels of loneliness, even if they only see most of those friends occasionally. Simply knowing that an old friend still remembers you fondly , researchers suggest, can make a person feel more secure and supported in daily life. This effect appears to hold true whether the reconnection happens through a long phone call, a short message, or even a chance meeting at a local event.", "Of course, not every attempt to reconnect goes smoothly. Some old friendships fade for good reasons, such as a serious disagreement, and reaching out again can feel awkward or unwelcome. Experts generally recommend starting with a short, low-pressure message rather than expecting an immediate deep conversation, since this gives the other person space to respond in whatever way feels comfortable to them . A simple message asking how someone has been doing is often enough to open the door.", "Social media has made reconnecting far easier than it used to be, since it allows people to see updates about an old friend's life without any pressure to respond right away. Still, many experts note that a real conversation, even a short one, usually builds a stronger connection than simply viewing someone's photos online. For this reason, some people now treat social media mainly as a first step, a way to find someone again before eventually sending a proper message."], questions: [{ q: "According to the passage, what kind of details might an old friend remember about you?", options: ["Details that a new friend would also already know", "Only information they found on social media", "An embarrassing haircut, a nickname, or a difficult period", "Only your current job and daily schedule"], answer: 2 }, { q: "What is the main idea of the passage?", options: ["Most old friendships fade because of serious, unavoidable disagreements", "Social media has completely replaced the need for real conversations", "New friends always understand a person better than old friends do", "Reconnecting with old friends can be easy and bring real emotional benefits"], answer: 3 }, { q: "The word \"rewarding\" in paragraph 1 is closest in meaning to _______.", options: ["unusual", "expensive", "confusing", "satisfying"], answer: 3 }, { q: "According to the passage, what have several studies found about people with a wider circle of long-term connections?", options: ["They always meet their old friends in person every week", "They report higher levels of loneliness than people with fewer friends", "They report feeling supported only through daily phone calls", "They tend to report lower levels of loneliness, even seeing friends occasionally"], answer: 3 }, { q: "According to the passage, which of the following is NOT mentioned as a way people can reconnect with an old friend?", options: ["Hiring a professional service to arrange a meeting", "Viewing updates through social media", "Sending a short, low-pressure message", "Meeting by chance at a local event"], answer: 0 }, { q: "The word \"them\" (in \"comfortable to them,\" paragraph 4) refers to _______.", options: ["old friendships in general", "experts who study friendship", "the person receiving the message", "social media platforms"], answer: 2 }, { q: "What do experts generally recommend when trying to reconnect with an old friend?", options: ["Sending several long messages within the same day", "Only reconnecting through in-person meetings, never by message", "Avoiding any contact until the other person reaches out first", "Starting with a short, low-pressure message instead of a deep conversation"], answer: 3 }, { q: "The word \"fondly\" in paragraph 3 is closest in meaning to _______.", options: ["briefly", "nervously", "rarely", "warmly"], answer: 3 }, { q: "What can be inferred from the passage about how some people now use social media when reconnecting?", options: ["As the only method experts recommend for reconnecting", "As a way to avoid contacting old friends altogether", "As a full replacement for any real conversation", "As a first step before eventually sending a proper message"], answer: 3 }, { q: "What is the author's overall attitude toward reconnecting with old friends?", options: ["Strongly critical, warning readers to avoid old friendships", "Generally positive, while acknowledging it does not always go smoothly", "Overly enthusiastic, insisting everyone should reconnect immediately", "Completely neutral, offering no view on the topic at all"], answer: 1 }] },
    { title: "Spotting the Fakes: The Rise of Untrustworthy Websites", paragraphs: ["Anyone who spends enough time online eventually encounters a website that looks convincing at first glance but turns out, on closer inspection, to be something else entirely — a fake news outlet dressed up as a legitimate newspaper, or an online store that never ships the products it advertises. Not only has the sheer number of such sites grown substantially over the past decade, but the tools used to build them have become sophisticated enough that even experienced internet users increasingly struggle to distinguish a fraudulent site from a genuine one within the first few seconds of visiting.", "Design quality, researchers studying online trust have found, turns out to be a surprisingly poor indicator of a website's legitimacy . Many fraudulent sites now use the same professional templates, stock photography, and layout conventions as established, reputable businesses, since these templates are widely available and inexpensive to purchase. A cluttered, outdated-looking website, once considered a reliable warning sign, may in fact belong to a small but entirely genuine local business that simply never updated its design, while a sleek, modern-looking site may belong to an operation created purely to collect payment information from unsuspecting visitors.", "What appears to matter more than visual polish, several studies suggest, is a cluster of less obvious signals that require slightly closer inspection: whether the site provides a verifiable physical address or phone number, whether independent reviews of the business exist outside the site itself, and whether the site's domain name was registered only recently despite claiming a long operating history. None of these signals alone proves fraud conclusively, researchers caution, but a site lacking several of them simultaneously warrants noticeably more caution than one lacking only a single indicator.", "Some fraudulent sites go further still, mimicking the domain names of well-known brands closely enough — through a single substituted letter, an added hyphen, or an unfamiliar domain ending — that a visitor scanning quickly may not notice the difference at all. This technique , sometimes called typosquatting, relies less on deceiving a careful reader than on exploiting the speed at which most people actually browse, since few visitors read a full web address character by character before clicking a search result or a link shared by a friend.", "Online marketplaces have complicated the picture further by hosting both legitimate third-party sellers and fraudulent ones within a single, seemingly trustworthy platform, meaning that a shopper's caution toward the platform as a whole does not necessarily transfer to caution toward each individual seller operating within it. Some marketplaces have responded with seller verification programs and buyer-protection policies, though critics note that enforcement varies considerably, and a policy's mere existence on paper does not guarantee it is consistently applied when a dispute actually arises.", "Taken together, this growing sophistication suggests that no single rule of thumb — checking for design quality, a secure connection icon, or a familiar-looking logo — can reliably separate genuine websites from fraudulent ones anymore. What consumer-protection researchers now generally recommend instead is a combination of smaller checks performed together, on the reasoning that a fraudulent site is far more likely to fail several less obvious tests at once than to fail every single one perfectly."], questions: [{ q: "According to the passage, what have researchers found about design quality as an indicator of a website's legitimacy?", options: ["It has become less important because most fraudulent sites now look outdated", "It only matters for websites that sell physical products", "It is the single most reliable indicator available to shoppers", "It is a poor indicator, as scam sites often look professional"], answer: 3 }, { q: "The word \"legitimacy\" in paragraph 2 is closest in meaning to _______.", options: ["profitability", "popularity", "genuineness", "simplicity"], answer: 2 }, { q: "What is the main idea of the passage?", options: ["Typosquatting is the only method fraudulent websites currently use", "Online marketplaces have completely eliminated fraudulent third-party sellers", "Fraudulent websites can now be identified only through their design quality", "No single sign reliably identifies fraud, so combining smaller checks works better"], answer: 3 }, { q: "According to the passage, which of the following is mentioned as a less obvious signal worth checking?", options: ["Whether the site uses a professionally designed layout template", "Whether the site's domain was recently registered despite claiming a long history", "Whether the site has more visitors than its competitors", "Whether the site loads quickly on a mobile device"], answer: 1 }, { q: "According to the passage, which of the following is NOT mentioned as a signal worth checking for a website's trustworthiness?", options: ["How recently the site's domain name was registered", "The total number of employees listed on the site", "Independent reviews existing outside the site itself", "A verifiable physical address or phone number"], answer: 1 }, { q: "The phrase \"this technique\" in paragraph 4 refers to _______.", options: ["mimicking well-known domain names with small changes", "checking a site's domain registration date", "using professional design templates to appear legitimate", "hosting third-party sellers within a marketplace"], answer: 0 }, { q: "According to the passage, what problem do online marketplaces create for shoppers?", options: ["Trusting the platform overall does not guarantee trust in each individual seller", "Marketplaces no longer allow any third-party sellers to operate", "Fraudulent sellers cannot operate within any well-known marketplace", "Buyer-protection policies are always enforced consistently across every dispute"], answer: 0 }, { q: "The word \"warrants\" in paragraph 3 is closest in meaning to _______.", options: ["prevents", "delays", "guarantees", "justifies"], answer: 3 }, { q: "What can be inferred from the passage about a marketplace's buyer-protection policy?", options: ["It applies only to sellers who have registered very recently", "It always fully protects buyers regardless of the seller involved", "It has completely replaced the need for shoppers to check other signals", "Its existence on paper does not ensure consistent practical enforcement"], answer: 3 }, { q: "What is the author's overall attitude toward how consumers should approach unfamiliar websites?", options: ["Alarmed, suggesting that online shopping should generally be avoided entirely", "Dismissive, treating concerns about fraudulent websites as exaggerated", "Cautiously practical, favoring multiple checks over a single rule", "Reassuring, arguing that modern websites are now almost always trustworthy"], answer: 2 }] },
    { title: "Rebuilding the Skyline: London's Construction Boom and Its Discontents", paragraphs: ["Anyone walking through central London over the past fifteen years will have noticed the skyline shifting almost continuously, as construction cranes replace older ones nearly as fast as buildings themselves rise. This visible transformation reflects a construction boom driven by a combination of pressures — chronic housing shortages, growing demand for modern office space, and the city's determination to remain internationally competitive — pressures that have collided repeatedly with an equally persistent, and considerably older, commitment to preserving the city's historic character.", "Nowhere has this tension proven more visible than in the long-running disputes over tall buildings near historically protected areas. Planning applications for new towers routinely proceed for years before a final decision is reached, not primarily because developers lack the financial resources to build quickly, but because proposals must satisfy an intricate, sometimes contradictory, set of viewpoint protections designed to preserve sightlines toward landmarks such as St Paul's Cathedral from specific, legally protected vantage points scattered across the city. A single building's design can be revised a dozen times before it satisfies every relevant protected view.", "Developers and heritage advocates disagree sharply, and predictably, about whether this system strikes a reasonable balance. Some architects argue that the protected-view framework, whatever its historical justification, has become excessively rigid, forcing awkward compromises in building design that satisfy the letter of the sightline rules while producing structures that few architects consider genuinely elegant. Heritage advocates counter that without such protections, London's most recognizable landmarks would gradually disappear behind a wall of undistinguished towers, and that the occasional awkward compromise is a modest price for preserving views that, once lost, could never realistically be recovered.", "Housing, meanwhile, presents a related but distinct set of pressures. London's chronic shortage of affordable housing has led local authorities to require that a proportion of units in most large residential developments be sold or rented below market rate, typically somewhere between twenty and forty percent depending on the borough and the specific site. Developers frequently argue that these requirements, layered on top of already high land and construction costs, make many potentially viable projects financially unworkable, while affordable-housing advocates counter that without firm requirements, developers would simply build almost none of the housing London most urgently needs.", "Construction delays compound both disputes considerably. A tower whose planning application alone takes three or four years to resolve may then face a further two to three years of construction, during which material costs, labor availability, and interest rates can all shift substantially, sometimes rendering a project's original financial assumptions obsolete well before the building is completed. Some developers have responded by building in significant cost contingencies from the outset, a practice that itself raises the price of the affordable-housing units the project is required to include, since those units must still meet the same minimum size and quality standards as market-rate units nearby.", "This dynamic, critics of the current planning system argue, produces a perverse outcome: regulations intended primarily to preserve heritage and secure affordable housing may, in combination with lengthy approval timelines, end up doing neither particularly well, since some viable projects are abandoned outright while those that do proceed often deliver fewer affordable units than initially proposed, following renegotiation once construction costs rise. Whether streamlining the approval process alone would meaningfully resolve either problem, without simultaneously weakening the very protections these delays are partly meant to enforce, remains a genuinely contested question among planning specialists.", "None of this suggests that London's approach to balancing development and preservation is straightforwardly mistaken, since cities that have prioritized speed over such protections have, in some documented cases, produced skylines widely regarded as having sacrificed too much historic character for short-term commercial gain. What the ongoing disputes do suggest is that London has not yet found a stable equilibrium between these competing priorities, and that each proposed reform tends to strengthen one goal only by placing additional strain on the other."], questions: [{ q: "According to the passage, why do planning applications for tall buildings near historic areas often take years to resolve?", options: ["Developers typically lack the financial resources needed to proceed quickly", "Proposals must satisfy a complex set of protected-view requirements", "Heritage advocates hold legal veto power over every new proposal", "Local authorities require public votes on every proposed building design"], answer: 1 }, { q: "The word \"obsolete\" in paragraph 5 is closest in meaning to _______.", options: ["flexible", "objective", "outdated", "expensive"], answer: 2 }, { q: "What is the main idea of the passage?", options: ["London's building boom creates ongoing tension between heritage protection and housing needs", "Developers in London always ignore affordable housing requirements when building towers", "London has successfully balanced development and preservation through its current planning system", "Heritage protections are the sole cause of London's affordable housing shortage"], answer: 0 }, { q: "According to the passage, what proportion of units in large residential developments must typically be sold or rented below market rate?", options: ["Somewhere between twenty and forty percent, depending on the borough and site", "Exactly fifty percent in every borough without exception", "A proportion set independently by each individual developer", "Less than ten percent in most large developments"], answer: 0 }, { q: "According to the passage, which of the following is NOT mentioned as a pressure or factor affecting London's construction disputes?", options: ["A citywide limit on the total number of new towers approved each year", "Viewpoint protections toward landmarks such as St Paul's Cathedral", "Rising material and labor costs during construction delays", "Affordable-housing percentage requirements varying by borough"], answer: 0 }, { q: "The phrase \"those units\" in paragraph 5 refers to _______.", options: ["the market-rate units built nearby", "the required affordable-housing units", "the planning applications submitted by developers", "the protected views near St Paul's Cathedral"], answer: 1 }, { q: "According to the passage, what perverse outcome do critics of the current planning system describe?", options: ["Regulations may fail to achieve their main goals", "Regulations have doubled the number of affordable units delivered on average", "Regulations apply only to buildings taller than a specific fixed height", "Regulations have completely eliminated all new tower construction in London"], answer: 0 }, { q: "The word \"perverse\" in paragraph 6 is closest in meaning to _______.", options: ["financially costly", "contrary to what was intended", "widely praised", "legally required"], answer: 1 }, { q: "What can be inferred from the passage about streamlining London's approval process on its own?", options: ["It has already been proven to solve both the heritage and housing problems fully", "It would definitely eliminate the need for any affordable-housing requirements", "It has been rejected by every planning specialist who has studied the issue", "It may speed up building but risk weakening key protections"], answer: 3 }, { q: "What is the author's overall purpose in the passage?", options: ["To examine the ongoing tension between preservation and development in London", "To criticize developers specifically for causing all construction delays", "To argue that London should abandon all heritage protections immediately", "To prove that London's planning system is more effective than any other city's"], answer: 0 }] },
    { title: "The Trouble with BMI: Measuring Obesity in an Imperfect Number", paragraphs: ["Body mass index, calculated simply by dividing a person's weight in kilograms by the square of their height in meters, has served for decades as the primary screening tool through which clinicians, insurers, and public health agencies classify individuals as underweight, normal weight, overweight, or obese. Not only has this single number shaped clinical guidelines and insurance calculations worldwide, but it continues to anchor most population-level obesity statistics even as a substantial and growing body of research has raised serious questions about how accurately it reflects the specific health risk it was originally designed to approximate.", "BMI's most frequently cited limitation is that it cannot distinguish between fat mass and lean muscle mass, since the formula accounts only for total body weight relative to height. A muscular athlete and a sedentary individual carrying substantial excess fat can register an identical BMI despite representing genuinely different metabolic health profiles, a discrepancy that becomes increasingly consequential as BMI is used not merely as a rough screening tool but, in many clinical and insurance contexts, as a threshold that directly determines eligibility for certain treatments, insurance premiums, or even employment-related health assessments.", "A related, somewhat less widely appreciated limitation concerns where excess fat is actually distributed on the body, a factor several large cohort studies now suggest may matter considerably more for cardiovascular and metabolic risk than total body fat alone. Fat concentrated around the abdomen, sometimes termed visceral fat, appears more strongly associated with elevated risk of heart disease and type 2 diabetes than fat distributed elsewhere on the body, yet two individuals with identical BMI values can carry dramatically different proportions of visceral versus subcutaneous fat, meaning that BMI alone may substantially understate risk for some individuals while overstating it for others, even at the very same numerical value.", "None of this means BMI lacks any predictive value whatsoever; at a population level, rather than for any single individual, BMI does correlate reasonably well with average rates of several chronic conditions, and its simplicity, requiring only a scale and a measuring tape, has made it far more practical for large-scale screening than more precise but considerably more expensive alternatives such as dual-energy X-ray absorptiometry. The tension, in other words, is not that BMI is simply wrong, but that a measure validated primarily at the population level is now routinely applied to individual clinical decisions for which it was never particularly well suited.", "Some researchers have proposed supplementing or replacing BMI with measures more directly sensitive to fat distribution, such as waist-to-hip ratio or waist circumference alone, both of which correlate somewhat more closely with cardiovascular risk in several studies, though neither has yet achieved BMI's near-universal adoption across clinical settings, insurance systems, and public health surveillance, partly because measurement consistency across different practitioners has proven harder to standardize than a simple height-and-weight calculation. Whether this practical barrier alone justifies BMI's continued dominance, given its documented individual-level limitations, remains a question several public health researchers now consider worth revisiting.", "Whether abandoning BMI in favor of these alternative measures would meaningfully improve individual clinical outcomes, or simply shift the same underlying measurement uncertainty onto a different, equally imperfect number, remains genuinely disputed among obesity researchers; some argue that any single-number screening tool will inevitably misclassify some individuals regardless of which specific formula is used, while others maintain that measures more directly tied to fat distribution, of the kind described earlier, would meaningfully reduce misclassification even if they could never eliminate it entirely.", "None of this settles precisely how clinicians should weigh BMI against emerging alternatives in individual patient care, a question current evidence cannot fully resolve. What the accumulated research does suggest, cautiously, is that treating a single population-validated number as a precise individual diagnostic risks both overstating and understating health risk for a meaningful share of patients, and that clinical practice built exclusively around BMI thresholds may be resting on a degree of individual-level precision the measure was never actually designed to provide."], questions: [{ q: "What is the main idea of the passage?", options: ["Visceral fat is the only factor that matters for cardiovascular health", "BMI helps population screening but lacks precision for individual diagnosis", "BMI has been completely replaced by waist-to-hip ratio in most clinical settings", "BMI accurately measures individual health risk for every patient regardless of body composition"], answer: 1 }, { q: "According to the passage, what is BMI's most frequently cited limitation?", options: ["It cannot distinguish between fat mass and lean muscle mass", "It has never been used in any insurance or employment context", "It applies only to individuals under a certain age", "It cannot be calculated without expensive specialized equipment"], answer: 0 }, { q: "The word \"discrepancy\" in paragraph 2 is closest in meaning to _______.", options: ["inconsistency", "discipline", "improvement", "discount"], answer: 0 }, { q: "According to the passage, what do several large cohort studies suggest about visceral fat?", options: ["It occurs only in individuals with a BMI classified as obese", "It links more strongly to heart and metabolic risks than overall body fat", "It can be measured more easily than total body fat using BMI alone", "It is unrelated to any measurable health risk according to current research"], answer: 1 }, { q: "According to the passage, which of the following is NOT mentioned as a limitation or challenge related to measuring obesity?", options: ["The average cost difference between BMI screening and blood pressure screening", "Differing proportions of visceral versus subcutaneous fat at the same BMI", "Difficulty standardizing waist measurements across different practitioners", "Inability to distinguish fat mass from lean muscle mass"], answer: 0 }, { q: "The phrase \"this practical barrier\" in paragraph 5 refers to _______.", options: ["the difficulty of calculating BMI without a calculator", "the difficulty of standardizing waist-based measurements across different practitioners", "the difficulty of persuading insurers to stop using BMI at all", "the difficulty of funding large cohort studies on visceral fat"], answer: 1 }, { q: "What can be inferred from the passage about replacing BMI with waist-to-hip ratio or waist circumference?", options: ["It may lower misclassification without fully solving measurement error", "It has already replaced BMI as the dominant measure in most healthcare systems", "It is guaranteed to eliminate all individual-level measurement error in clinical practice", "It would make population-level obesity statistics impossible to calculate"], answer: 0 }, { q: "The word \"misclassify\" in paragraph 6 is closest in meaning to _______.", options: ["publicly announce", "permanently exclude", "incorrectly categorize", "financially penalize"], answer: 2 }, { q: "What is the author's overall attitude toward the continued use of BMI in individual clinical decisions?", options: ["Neutral, presenting no evaluation of BMI's appropriateness at all", "Dismissive, arguing BMI has no value at any level of analysis", "Skeptical about using population metrics for individuals", "Fully supportive, arguing BMI remains the best possible measure for every patient"], answer: 2 }, { q: "According to the passage, what does the passage say about BMI's validity at the population level compared to the individual level?", options: ["BMI was originally designed specifically for individual clinical diagnosis, not population screening", "BMI is equally precise at both the population and individual levels", "BMI suits large-scale population tracking better than individual diagnosis", "BMI has no demonstrated correlation with chronic disease at any level"], answer: 2 }] },
  ] },
];
